<div class="page-heading"><div><p class="eyebrow"><?= e(t('LOCAL SNAPSHOT')) ?></p><h1><?= e($title) ?></h1><p><?= e($report['starts_on']) ?> <?= e(t('to')) ?> <?= e((new DateTimeImmutable($report['ends_before']))->modify('-1 day')->format('Y-m-d')) ?> <?= e(t('· Asia/Colombo')) ?></p></div><a href="/insights#alerts" class="btn secondary"><?= e(t('Review & insights')) ?></a></div>
<section class="card"><h2><?= e(t('Your recorded activity')) ?></h2><dl><?php foreach (['tasks_done'=>t('Tasks completed'),'income'=>t('Income recorded'),'expenses'=>t('Spending recorded'),'habit_checkins'=>t('Habit check-ins'),'focus_minutes'=>t('Completed study minutes')] as $key=>$label): if ($report['kind']==='monthly' && !in_array($key,['income','expenses'],true)) continue; ?><div class="task-row"><dt><?= e($label) ?></dt><dd><strong><?= $report['summary'][$key]===null ? t('Module not enabled') : (in_array($key,['income','expenses'],true) ? e(money($report['summary'][$key])) : e($report['summary'][$key])) ?></strong></dd></div><?php endforeach; ?></dl><p class="footnote"><?= e(t('This is a saved snapshot from the time the routine ran. Later edits do not change it. Old completed tasks without a known completion date are excluded. Financial totals use recorded income and expense dates; transfers and planned bills are excluded.')) ?></p><p class="muted"><?= e(t('Use Ctrl+P and choose Save as PDF to share or keep this report.')) ?></p></section>
